// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/health", wrapper.GetHealth)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/auth/google", wrapper.SignInWithGoogle)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/auth/microsoft", wrapper.SignInWithMicrosoft)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/auth/apple", wrapper.SignInWithApple)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/auth/facebook", wrapper.SignInWithFacebook)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/v1/me", wrapper.DeleteMe)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/me", wrapper.GetMe)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/v1/me", wrapper.UpdateMe)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/me/consents", wrapper.ListConsents)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/me/consents", wrapper.AcceptConsent)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/v1/me/consents/{consent_type}", wrapper.RevokeConsent)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/me/patient", wrapper.GetPatientProfile)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/v1/me/patient", wrapper.UpdatePatientProfile)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/me/patient", wrapper.CreatePatientProfile)

	return m
}

